<?php
namespace App\Http\Controllers\Api;use App\Http\Controllers\Controller;use App\Http\Requests\{InitializeCheckoutRequest,QuoteCheckoutRequest};use App\Models\{Order,Payment};use App\Services\Commerce\CheckoutService;use Illuminate\Http\{JsonResponse,Request};class CheckoutController extends Controller{public function quote(QuoteCheckoutRequest$r,CheckoutService$c):JsonResponse{return response()->json(['data'=>$c->quote($r->validated('items'))]);}public function initialize(InitializeCheckoutRequest$r,CheckoutService$c):JsonResponse{return response()->json(['data'=>$c->initialize($r->validated(),auth('sanctum')->id())],201);}public function show(Request$r,string$id,CheckoutService$c):JsonResponse{$o=Order::where('public_id',$id)->firstOrFail();$c->authorizeOrderAccess($o,auth('sanctum')->id(),$r->header('X-Checkout-Token'));return response()->json(['data'=>$c->publicOrderPayload($o)]);}public function verify(Request$r,string$ref,CheckoutService$c):JsonResponse{$p=Payment::where('reference',$ref)->with('order')->firstOrFail();$c->authorizeOrderAccess($p->order,auth('sanctum')->id(),$r->header('X-Checkout-Token'));return response()->json(['data'=>$c->publicOrderPayload($c->verify($ref))]);}}